SELECT 

WHERE d.kind = #{kind}
AND d.doc_no LIKE CONCAT('%', #{q.docNo}, '%')
AND o.order_no LIKE CONCAT('%', #{q.orderNo}, '%')
AND d.order_id = #{q.orderId}
AND d.partner_id = #{q.partnerId}
AND (d.warehouse_id = #{q.warehouseId} OR EXISTS (SELECT 1 FROM scm_trade_draft_item ti
    WHERE ti.draft_id = d.id AND ti.warehouse_id = #{q.warehouseId}))
AND d.biz_date >= #{q.beginDate}
AND d.biz_date <= #{q.endDate}
ORDER BY d.id DESC
